new Promise(function(res){var a=new Image();a.onload=function(){var b=new Image();b.onload=function(){try{var cv=document.createElement('canvas');cv.width=333;cv.height=261;var g=cv.getContext('2d');g.drawImage(b,0,0,333,261);var da=g.getImageData(0,0,333,261).data;var ca=document.createElement('canvas');ca.width=333;ca.height=261;var ga=ca.getContext('2d');ga.drawImage(a,0,0,333,261);var dd=ga.getImageData(0,0,333,261).data;var sum=0;for(var i=0;i<da.length;i+=4){sum+=Math.abs(da[i]-dd[i])+Math.abs(da[i+1]-dd[i+1])+Math.abs(da[i+2]-dd[i+2]);}var mean=sum/(333*261*3);var gray=0;for(var y=60;y<261;y++){var row=ga.getImageData(0,y,333,1).data,run=0,mx=0;for(var x=0;x<333;x++){var R=row[x*4],G=row[x*4+1],B=row[x*4+2];if(Math.abs(R-G)<=3&&Math.abs(G-B)<=3&&R>=200&&R<=245){run++;if(run>mx)mx=run;}else run=0;}if(mx>=200)gray++;}res(JSON.stringify({meanAbsDiff:mean, userGrayRows:gray, userSize:[a.naturalWidth,a.naturalHeight], mineSize:[b.naturalWidth,b.naturalHeight]}));}catch(e){res('EXC:'+e.message);}};b.onerror=function(){res('BERR');};b.src='data:image/png;base64,';};a.onerror=function(){res('AERR');};a.src='data:image/png;base64,';})